/// <reference types="vite/client" />

/** Injected by vite.config.ts (`define`): package.json version and the short commit hash of the build. */
declare const __APP_VERSION__: string;
declare const __APP_BUILD__: string;
/** The one language a build is fixed to ('en': the overseas portal build, `pnpm build:en`); '' for the web build. */
declare const __BUILD_LANG__: string;
